    {const plinth=new THREE.Mesh(new THREE.CylinderGeometry(R0*1.5,R0*1.62,7,9).translate(0,3.5,0),stoneM);plinth.position.set(x,g0-1,z);parts.push(plinth);}   // the plaza steps up to it
